// Glossary of the terms the lessons use. Each term is defined once here, in both site languages,
// in the wording of the AWS documentation, links to the AWS documentation page it is based on,
// and points to the lesson that teaches it. The /glossary/ page lists every term; each lesson
// scene shows a "key terms" strip with the terms its text uses (see glossary-scan.ts, build time).
//
// Matching: every alias is looked up as a whole word. An alias written in capitals only (an
// acronym such as "AZ" or "EC2") matches with that exact case; any other alias ignores case.
// Longer aliases win over shorter ones, so "NAT gateway" is not also counted as "gateway".
//
// `flow` draws a small figure on the card: boxes joined by the arrow tokens in FLOW_ARROWS (glossary-rules.ts).

export interface GlossaryText {
  /** Definition, following the AWS documentation. */
  def: string;
  /** How MFTECH uses it; optional. */
  example?: string;
}

export interface GlossaryTerm {
  /** URL anchor on /glossary/: lower case, digits and dashes. */
  id: string;
  /** Display name, written the way AWS writes it. */
  name: string;
  /** Lesson id (curriculum.ts) that teaches the term. */
  lesson: string;
  /** Extra spellings found in lesson text, in either language. The name counts as one when it has no brackets. */
  aliases: string[];
  /** AWS documentation page the definition follows. */
  docs: string;
  /** Optional figure: box labels and arrow tokens, left to right; "vi|en" gives a label in both languages. */
  flow?: string[];
  vi: GlossaryText;
  en: GlossaryText;
}


const D = "https://docs.aws.amazon.com/";

function term(
  id: string,
  name: string,
  lesson: string,
  aliases: string[],
  docs: string,
  flow: string[] | undefined,
  vi: [string, string?],
  en: [string, string?],
): GlossaryTerm {
  return { id, name, lesson, aliases, docs: docs.startsWith("http") ? docs : D + docs, flow, vi: { def: vi[0], example: vi[1] }, en: { def: en[0], example: en[1] } };
}

